package contracts

import (
	_ "embed"
	"encoding/json"
	"strings"
)

// commands.json is generated by scripts/export-contract.cjs from the pinned
// @remnawave/backend-contract; status.json holds the success status each
// upstream controller returns for those commands.
var (
	//go:embed commands.json
	commandsJSON []byte
	//go:embed status.json
	statusJSON []byte
	// OpenAPI is the OpenAPI 3.1 document generated from the contract's zod
	// schemas (scripts/export-contract.cjs --openapi).
	//go:embed openapi.json
	OpenAPI []byte
)

// Command is one operation of the pinned upstream contract.
type Command struct {
	Name   string `json:"name"`
	Method string `json:"method"`
	Path   string `json:"path"`
	Scope  string `json:"scope"`
	Kind   string `json:"kind"`
	// Status is the upstream success status (200, 201, 202 or 204).
	Status int `json:"-"`
}

// Version is the pinned contract version.
var Version string

// Commands lists every contract operation.
var Commands = loadCommands()

func loadCommands() []Command {
	var file struct {
		Version  string    `json:"version"`
		Commands []Command `json:"commands"`
	}
	if err := json.Unmarshal(commandsJSON, &file); err != nil {
		panic(err)
	}
	var statuses map[string]int
	if err := json.Unmarshal(statusJSON, &statuses); err != nil {
		panic(err)
	}
	Version = file.Version
	for i := range file.Commands {
		file.Commands[i].Status = statuses[file.Commands[i].Name]
		if file.Commands[i].Status == 0 {
			file.Commands[i].Status = 200
		}
	}
	return file.Commands
}

// FindCommand matches a request to the most specific contract command; literal
// segments outrank ":param" segments, so /api/users/stream beats /api/users/:id.
func FindCommand(method, path string) (Command, bool) {
	segments := strings.Split(strings.Trim(path, "/"), "/")
	var best Command
	bestScore := -1
	for _, command := range Commands {
		if command.Method != method {
			continue
		}
		pattern := strings.Split(strings.Trim(command.Path, "/"), "/")
		if len(pattern) != len(segments) {
			continue
		}
		score, matches := 0, true
		for i, part := range pattern {
			if strings.HasPrefix(part, ":") {
				continue
			}
			if part != segments[i] {
				matches = false
				break
			}
			score++
		}
		if matches && score > bestScore {
			best, bestScore = command, score
		}
	}
	return best, bestScore >= 0
}
